		hasPrototype = false;
		proto = null;
		renderFn = null;
		if (typeof parentType == 'function') {
			proto = parentType.prototype;
			if (proto != null) {
				renderFn = proto.render;
				if (typeof renderFn == 'function') {
					hasPrototype = true;
				}
			}
		}

		component = vnode._component;
		if (!component) {
			if (typeof parentType == 'string') {
				continue;
			}
			if (parentType == null) {
				continue;
			}
			continue;
		}
		if (component._processingException) {
			continue;
		}

