						nextState = component._nextState;
					} else {
						copiedState = {};
						for (propName in prevState) {
							copiedState[propName] = prevState[propName];
						}
						nextState = copiedState;
						component._nextState = nextState;
					}

					if (typeof update == 'function') {
						stateSnapshot = assign({}, nextState);
						if (nextProps != null) {
